Let $\delta>0$ and let $b$ be an integer that is sufficiently large in terms of $\delta$. Let $\xi:\mathbb{N}\rightarrow\mathbb{R}$ be a well-factorable arithmetic function of level $D\in [1, X^{1/2-\delta}]$. Let $c$ be a non-zero integer and let $r\in \mathcal{A}\cap[0,b)$ be such that $(r, b)=1$. Then, for any $A>0$, we have
\begin{align}
 \sum_{\substack{d\leq D\\ (d,bc)=1}}\xi(d)\mathcal{E}(X; d, c; b, r) \ll_{A,b,\delta}\dfrac{X^{\zeta}}{(\log X)^A}.
\end{align}

Let $\delta>0$ and let $b$ be an integer that is sufficiently large in terms of $\delta$. Let $D\in [1, X^{1/3-\delta}]$ and let $r\in \mathcal{A}\cap[0, b)$ be an integer such that $(r, b)=1$. Then for any $A>0$, we have
\begin{align}
 \sum_{\substack{d\leq D\\(d,b)=1}}\max_{(c,d)=1}\big|\mathcal{E}(X;d,c;b,r)\big| \ll_{A, b, \delta} \dfrac{X^{\zeta}}{(\log X)^A}.
\end{align}

Let $\varepsilon>0$ be small. Let $\delta \in (0, 10^{-3}]$ and let $b$ be an odd integer that is sufficiently large in terms of $\delta$. Let $r\in \mathcal{A}\cap[0, b)$ with $(r(r-1), b)=1$. Let $\lambda^-_{\textup{sem}}$ be as in Lemma 3.3 and Lemma 3.4 with $z_1\leq X^{1/3-2\delta-2\varepsilon^2}$ and $D=X^{\rho_{\textup{sem}}}$, where $\rho_{\textup{sem}}=3(1-4\delta)/7-\varepsilon$. Then for any $A>0$, we have
\begin{align} 
\sum_{\substack{d\leq D\\(d,2b)=1}}\lambda^-_{\textup{sem}}(d)\Bigg(\sum_{\substack{n < X\\n\equiv 1 \ (\mathrm{mod}\ d)\\n\equiv 3\ (\mathrm{mod}\ 8)}}\Lambda(n)1_{\mathcal{A}_r}(n) - \dfrac{1}{4\varphi(d)}\dfrac{b}{\varphi(b)}\sum_{\substack{n<X}}1_{\mathcal{A}_r}(n)\Bigg) \ll_{A, b, \delta, \varepsilon} \dfrac{X^{\zeta}}{(\log X)^A}.
\end{align}

Let $\varepsilon>0$ be small. Let $\delta\in (0, 10^{-3}]$ and let $b$ be an odd integer that is sufficiently large in terms of $\delta$. Let $r\in \mathcal{A}\cap[0,b)$ with $(r, b)=(r-1, b)=1$. Let $L$ be a real number such that $L\in[X^{1/3-2\delta-\varepsilon}, X^{2/3+2\delta + \varepsilon}]$. Suppose $\mathfrak{h}$ is a bounded arithmetic real-valued function, and $\lambda^+_{\textup{lin}}$ is as in Lemma 3.5 and Lemma 3.6 with $z_2=X^{1/5}$, and $D=X^{\rho_{\textup{lin}}}$ for $\rho_{\textup{lin}}=1/2-2\delta-\varepsilon$. Then for any $A>0$, we have
\begin{align}
 \sum_{\substack{d \leq X^{1/2-2\delta}\\(d,2b)=1}}\lambda^+_{\textup{lin}}(d)\bigg(\sum_{\substack{\ell\sim L\\(\ell,2b)=1}}\mathfrak{h}(\ell)&\sum_{\substack{n< X/2\ell\\2\ell n+1\equiv 0\ (\mathrm{mod}\ d)\\ \ell n\equiv 1\ (\mathrm{mod}\ 4)}}1_{\mathcal{A}_r}(2\ell n+1)\Lambda(n)\\
 &-\dfrac{1}{4\varphi(d)}\dfrac{b}{\varphi(b)}\sum_{\substack{\ell \sim L\\(\ell, 2bd)=1}}\dfrac{\mathfrak{h}(\ell)}{\ell}\sum_{n<X}1_{\mathcal{A}_r}(n)\bigg)\ll_{A, b, \delta, \varepsilon} \dfrac{X^{\zeta}}{(\log X)^A}.
\end{align}

Let $C\geq 1$ be a large real number. Assume the setting of Theorem 7 and recall that $s$ is a positive integer such that $(r-s, b)=1$. Then we have
\begin{align}
 \sum_{\substack{d\leq D\\(d, b)=1}}\max_{(c, d)=1}\bigg\lvert\dfrac{1}{X}\sum_{\substack{0\leq t<X\\t\in \mathfrak{M}}}\widehat{1}_{\mathcal{A}_r}\bigg(\dfrac{t}{X}\bigg)\widehat{\mathfrak{f}}_{d, c}\bigg(\dfrac{-t}{X}\bigg)e\bigg(\dfrac{-st}{X}\bigg)-\dfrac{\lambda_{d}}{\varphi(d)}\dfrac{b}{\varphi(b)}\sum_{\substack{n< X}}1_{\mathcal{A}_r}(n)\bigg| \ll\dfrac{X^{\zeta}}{(\log X)^{5C+5}},
\end{align}
where $\mathfrak{M}$ is given by the relation (2.7), and the implicit constant in $\ll$ depends at most on $b$, $C$ and $\delta$.

Let $Q, B\geq 1$ with $QB \ll X^{1/2}$. Assume the set-up of Theorem 7. Then we have
\begin{align}
  \sum_{q\sim Q}\sum_{\substack{a=1\\(a,q)=1}}^q\sum_{\substack{B< |\eta|+1\leq 2B\\X a/q+\eta \in \mathbb{Z}}}\bigg|\widehat{1}_{\mathcal{A}_r}\bigg(\frac{a}{q}+\frac{\eta}{X}\bigg)\sum_{\substack{d\leq D\\(d, b)=1}}{\sigma}(d)\widehat{\mathfrak{f}}_{d, c_d}\bigg(-\bigg(\frac{a}{q}+\frac{\eta}{X}\bigg)\bigg)\bigg|\\
 \ll X^{1+\zeta}\bigg(\dfrac{1}{(Q^2B)^{\omega/2-\alpha_b}} + \dfrac{X^{\alpha_b}}{X^{\omega/2}}\bigg)(\log X)^{C'},
\end{align}
where $\widehat{1}_{\mathcal{A}_r}, \widehat{\mathfrak{f}}_{d, c_d}$, and $\alpha_b$ are given by (2.2), (8.6), and (9.4), respectively. Furthermore, $\omega$ and $C'$ are as in condition Cond 3 of Theorem 7, and  the implicit constant in $\ll$ depends at most on $b$, $\delta$, and $\omega$.

Let $Q, B \geq 1$. Then, we have 
\begin{align}
 \sum_{q\sim Q}\sum_{\substack{1\leq a<q\\(a, q)=1}}\sum_{\substack{|\eta|<B\\b^k a/q + \eta \in \mathbb{Z}}}\bigg|\widehat{1}_{\mathcal{A}_r}\bigg(\frac{a}{q} + \frac{\eta}{b^k}\bigg)\bigg| \ll_{b} (b-1)^k(Q^2B)^{\alpha_b} + Q^2B(C_b\log b)^k,
\end{align}
where $C_b$ is the constant described in Lemma 9.1, and
\begin{align}
 \alpha_b = \dfrac{\log \bigg(C_b\dfrac{b\log b}{b-1}\bigg)}{\log b}.
\end{align}

Let $q<b^{k/3}$ be of the form $q=q_1q_2$ with $(q_1, b)=1$ and $q_1\neq 1$, and let $|\varepsilon| < 1/2b^{2k/3}$. Then, for any integer $a$ with $(a, q)=1$, we have
\begin{align}
 \bigg|\widehat{1}_{\mathcal{A}_r}\bigg(\frac{a}{q}+\varepsilon\bigg)\bigg| \ll_{b} (b-1)^k\exp\bigg(-c_b\dfrac{k}{\log q}\bigg),
\end{align}
for some constant $c_b>0$ depending only on $b$.

Let $\delta>0$ and let $b$ be an integer that is sufficiently large in terms of $\delta$. Let $k$ be a positive integer and set $X:=b^k$. Let $D$ be a real number such that $D\in [1, X^{1/2})$. Let $r\in \mathcal{A}\cap [0, b)$ with $(r, b)=1$ and let $s$ be a positive integer such that $(r-s, b)=1$. Let $\mathfrak{f}$ be an arithmetic function supported on integers co-prime to $b$ and $|\mathfrak{f}|\ll \log $. Suppose there exists an arithmetic function ${\sigma}$ such that ${\sigma}$ is supported on $[1, D]$, $|{\sigma}|\leq \uptau$, and
for each $d$ in the support of ${\sigma}$, $c_d$ is some reduced residue class modulo $d$. Furthermore, assume that the following three conditions hold.
\begin{enumerate}[(a)]
\item  (Partial sum estimate) For any $y\in [X^{3/4}, X]$, for any $A>0$ and for any integer $d \in [1, X)$, there exists a parameter $\lambda_d$ such that $|\lambda_d|\ll \log X$ and the relation
\begin{align}
 \sum_{\substack{n\leq y\\(n, d)=1}}\mathfrak{f}(n)= &y\lambda_{ d} + O_{A, b}\bigg(\dfrac{y}{(\log y)^A}\bigg)
\end{align}
holds.
\item   (Equidistribution estimate in arithmetic progressions)  For any $A, C>0$, we have 
\begin{align}
 \sum_{\substack{d\leq D\\(d, b)=1}}\sum_{\substack{q\leq (\log X)^{C}\\q|X}}\max_{(c, d)=1}\max_{(m, q)=1}\max_{X^{3/4}\leq y \leq X}\Bigg|\sum_{\substack{n\leq y\\n\equiv c\ (\mathrm{mod}\ d)\\ n\equiv m\ (\mathrm{mod}\ q) }}\mathfrak{f}(n)-\dfrac{ y\lambda_{d}}{\varphi(dq)}\Bigg| \ll_{A, C, b} \dfrac{X}{(\log X)^A},
\end{align}
where $\lambda_d$ is as described in condition Cond 1.

\item  (Exponential sum estimate)
Consider $\theta =a/q+\beta$ with $(a, q)=1$ and $|\beta|<1/q^2$. Furthermore, let $H=1+|\beta|X$ and $qH\in [1, X]$. Let $\omega$ be such that $\omega \in (0, 1)$ and $\alpha_b < \omega/2$ (where $\alpha_b$ is given by the relation (9.4)). Then there exists an absolute constant $C'>0$ such that

\begin{align}
 \sum_{\substack{d\leq D\\(d, b)=1}}{\sigma}(d)\sum_{\substack{n< X\\n\equiv c_d \ (\mathrm{mod}\ d)}}\mathfrak{f}(n)e(n\theta) \ll_{b, \delta, \omega
} X\bigg(\dfrac{(qH)^\omega}{X^\omega} + \dfrac{1}{(qH)^\omega}\bigg)(\log X)^{C'}.
\end{align}
\end{enumerate}
Then, for any $A>0$, we have
\begin{align}
 \sum_{\substack{d\leq D\\(d, b)=1}}{\sigma}(d)\bigg(\sum_{\substack{n < X\\n\equiv c_d \ (\mathrm{mod}\ d)}}\mathfrak{f}(n)1_{\mathcal{A}_r}(n+s) - \dfrac{\lambda_{d}}{\varphi(d)}\dfrac{b}{\varphi(b)}\sum_{\substack{n<X}}1_{\mathcal{A}_r}(n)\bigg) \ll\dfrac{X^{\zeta}}{(\log X)^A},
\end{align}
where the implicit constant in Vinogradov's notation $\ll$ depends at most on $A$, $b$, $\delta$, and $\omega$.

Let $\delta>0$, let $b$ be a fixed positive integer, and let $D\leq X^{1/3-\delta}$. Let $\theta= a/q + \beta$ with $(a, q)=1$ and $\lvert \beta\rvert <1/q^2$. Furthermore, let $H=1+|\beta|X$ and $qH\in [1, X]$. Then for some constant $C_1$, we have 
\begin{equation}
\sum_{\substack{d\leq D\\(d,b)=1}}\max_{(c,d)=1}\bigg\lvert\sum_{\substack{n<X\\n \equiv c \ (\mathrm{mod}\ d)\\(n, b)=1}}\Lambda(n)e(n\theta)\bigg\rvert \ll_{b, \delta} X\bigg(\dfrac{(qH)^{\delta/2}}{X^{\delta/2}} + \dfrac{1}{(qH)^{\delta/2}}\bigg)(\log X)^{C_1}.
\end{equation}

Let $\delta>0$ be small, and let $b$ be a fixed positive integer. Let $D_1\in [1, X^{1/3-\delta}]$ and $D_2\in [1, X^{1/9}]$. Let $\theta= a/q + \beta$ with $(a, q)=1$ and $|\beta|<1/q^2$. Furthermore, let $H=1+|\beta|X$ and $qH\in [1, X]$. Let $c$ be a fixed non-zero integer. Then for some constant $C_2>0$, we have
\begin{align}
\sum_{d_1\leq D_1}\sideset{}{^*}\sum_{\substack{d_2\leq D_2}}\bigg\lvert \sum_{\substack{n< X\\n \equiv c \ (\mathrm{mod}\ d_1d_2)\\(n, b)=1}}\Lambda(n)e(n\theta)\bigg\rvert \ll_{b, \delta}  X\bigg(\dfrac{(qH)^{\delta/2}}{X^{\delta/2}} + \dfrac{1}{(qH)^{\delta/2}}\bigg)(\log X)^{C_2},
 \end{align}
 where $*$ in the sum denotes the conditions $(d_1, d_2)=(d_1d_2, bc)=1$.

Let $\delta>0$ and let $b$ be a fixed positive integer. Let $c$ be a fixed non-zero integer and let $\xi:\mathbb{N}\rightarrow\mathbb{R}$ be a well-factorable function of level $D\in [1, X^{1/2-\delta}]$ with $|\xi|\leq 1$. Let $\theta= a/q + \beta$ for some $(a, q)=1$ and $\lvert \beta\rvert <1/q^2$. Furthermore, let $H=1+|\beta|X$ and $qH\in [1, X]$. Then for some constant $C_3>0$, we have 
\begin{equation}
 \sum_{\substack{d\leq D\\(d,bc)=1}}\xi(d)\sum_{\substack{n<X\\n \equiv c \ (\mathrm{mod}\ d)\\(n, b)=1}}\Lambda(n)e(n\theta)\ll_{b, \delta}  X\bigg(\dfrac{(qH)^{\delta/2}}{X^{\delta/2}} + \dfrac{1}{(qH)^{\delta/2}}\bigg)(\log X)^{C_3}.
\end{equation}

Let $\varepsilon>0$ be small and let $\delta\in (0, 10^{-3}]$. Let $b$ be a fixed positive integer. Let $\lambda_{\textup{sem}}^-$ be a lower bound semi-linear sieve weights of level $D\in [2, X^{\frac{3}{7}(1-4\delta)-\varepsilon}]$, as given in Lemma 3.3 and Lemma 3.4. Let $\theta= a/q + \beta$ with $(a, q)=1$ and $\lvert \beta\rvert <1/q^2$. Furthermore, let $H=1+|\beta|X$ and $qH\in [1, X]$. Then, for some constant $C_4>0$, we have 
\begin{equation}
\sum_{\substack{d\leq D\\(d,2b)=1}}\lambda_{\textup{sem}}^-(d)\sum_{\substack{n<X\\n \equiv 1 \ (\mathrm{mod}\ d)\\ n\equiv 3\ (\mathrm{mod}\ 8)\\(n, b)=1}}\Lambda(n)e(n\theta)\ll_{b, \delta, \varepsilon}  X\bigg(\dfrac{(qH)^{\delta/2}}{X^{\delta/2}} + \dfrac{1}{(qH)^{\delta/2}}\bigg)(\log X)^{C_4}.
\end{equation}

Let $\varepsilon>0$ be small and let $\delta\in (0, 10^{-3}]$. Let $b$ be a fixed positive integer. Let $\lambda_{\textup{lin}}^+$ be an upper bound linear sieve  weights of level $D\in [2, X^{1/2-2\delta-\varepsilon}]$, as given in Lemma 3.5 and Lemma 3.6. Let $L$ be a real number such that $L\in [X^{1/3-2\delta-\varepsilon}, X^{2/3+2\delta+\varepsilon}]$ and let $\mathfrak{h}$ be a bounded arithmetic real-valued function. Let $\theta= a/q + \beta$ with $(a, q)=1$ and $|\beta|<1/q^2$. Furthermore, let $H=1+|\beta|X$ and $qH\in [1, X]$. Then for some constant $C_5>0$, we have 
\begin{align}
 \sum_{\substack{d\leq D\\(d,\: 2b)=1}}\lambda_{\textup{lin}}^+(d)\sum_{\substack{\ell\sim L\\(\ell,b)=1}}\mathfrak{h}(\ell)&\sum_{\substack{n<X/2\ell\\2\ell n+1\equiv 0\ (\mathrm{mod}\ d)\\ \ell n\equiv 1\ (\mathrm{mod}\ 4)\\(n,b)=1}}\Lambda(n)e\Big((2\ell n+1)\theta\Big)\\
\ll_{b, \delta, \varepsilon} &  X\bigg(\dfrac{(qH)^{\delta}}{X^\delta} + \dfrac{1}{(qH)^\delta}\bigg)(\log X)^{C_5}.
\end{align}

Let $b$  be a sufficiently large odd integer and $r \in \mathcal{A}\cap[0, b)$ be such that $(r, b)=(r-1, b)=1$. Then, we have
\begin{align}
 \sum_{\substack{p<X\\p\equiv r\ (\mathrm{mod}\ b)}}1_{\mathcal{A}}(p)1_{\mathbb{B}}(p-1)\ll_{b} \dfrac{X^{\zeta}}{(\log X)^{3/2}}.
\end{align}

Assume the above sieve set-up. Let $\varepsilon>0$ be small. Let $\delta\in (0, 10^{-3}]$ and let $b$ be an odd integer that is sufficiently large in terms of $\delta$. Let $\alpha=(1/3-2\delta)^{-1}+\varepsilon$ be such that $\alpha\in [2, 4)$ and let $\rho_{\textup{sem}}\leq \frac{3}{7}(1-4\delta)-\varepsilon$. Then we have 
\begin{align}
 S\geq \dfrac{\mathfrak{S}+ o(1)}{(\log X)^{3/2}}\dfrac{b}{\varphi(b)}\prod_{\substack{p|b\\p\equiv 3\ (\mathrm{mod}\ 4)}}\bigg(1-\dfrac{1}{p-1}\bigg)^{-1}I_{\textup{sem}}(\rho_{\textup{sem}}, \alpha)\sum_{\substack{n<X}}1_{\mathcal{A}_r}(n),
\end{align}
where
\begin{align}
 \mathfrak{S} &=\dfrac{1}{4\sqrt{2}}\prod_{p\equiv 3\ (\mathrm{mod}\ 4)}\bigg(1-\dfrac{1}{p^2}\bigg)^{1/2}\prod_{p\equiv 3\ (\mathrm{mod}\ 4)}\bigg(1-\dfrac{1}{(p-1)^2}\bigg)
\end{align}
and
\begin{align}
 I_{\textup{sem}}(\rho_{\textup{sem}}, \alpha)&=\dfrac{1}{\sqrt{\rho_{\textup{sem}}}}\int_{1}^{\alpha \rho_{\textup{sem}}} \dfrac{\textup{d}y}{\sqrt{y(y-1)}}.
\end{align}

Assume the above sieve set-up. Let $\varepsilon>0$ be small. Let $\delta\in (0, 10^{-3}]$ and let $b$ be an odd integer that is sufficiently large in terms of $\delta$. Let $\alpha=(1/3-2\delta)^{-1} + \varepsilon$ be such that $\alpha\in [2, 4)$ and let $\rho_{\textup{lin}}\leq \frac{1}{2}-2\delta-\varepsilon$. Then we have
\begin{align}
 T\leq \dfrac{10\mathfrak{S}+o(1)}{9(\log X)^{3/2}} \dfrac{b}{\varphi(b)}\prod_{\substack{p|b\\p\equiv 3\ (\mathrm{mod}\ 4)}}\bigg(1-\dfrac{1}{p-1}\bigg)^{-1}I_{\textup{lin}}(\rho_{\textup{lin}}, \alpha)\sum_{\substack{n<X}}1_{\mathcal{A}_r}(n),
\end{align}
where $\mathfrak{S}$ is given by the relation (4.10) and
\begin{align}
 I_{\textup{lin}}(\rho_{\textup{lin}}, \alpha)=\dfrac{1}{\rho_{\textup{lin}}}\int_{2}^\alpha\dfrac{\log (y-1)}{y(1-y/\alpha)^{1/2}}\textup{d}y.
\end{align}

Let $b$ be an odd integer that is sufficiently large, and let 
\[\mathbb{B}=\{n:n=n_1^2+n_2^2~~\text{for some}~(n_1, n_2)=1\}.\]
Let $r\in \mathcal{A}\cap[0, b)$ with $\big(r(r-1), b\big)=1$. Then, we have
\begin{equation}
 \sum_{\substack{p < X\\p\equiv r\ (\mathrm{mod}\ b)}}1_{\mathcal{A}}(p)1_{\mathbb{B}}(p-1)\asymp_{b} \dfrac{X^{\zeta}}{(\log X)^{3/2}}.
\end{equation}

Consider a sequence $\mathcal{C}=\big(c(n)\big)_{n=1}^\infty$ of non-negative real numbers and a set of primes $\mathcal{P}$ satisfying axioms A1, A2, and A4 with $\varkappa = 1/2$. If $u_1>0$ and $D=z_1^{u_1}$, then there exist two arithmetic functions $\lambda^\pm_{\textup{sem}}: \mathbb{N}\rightarrow [-1, 1]$ supported on the set $\{d|P(z_1): d\leq D\}$, and we have 
\begin{equation}
S(\mathcal{C}, \mathcal{P}, z_1) \geq C(x)\bigg\{f_{\textup{sem}}(u_1) + o(1)\bigg\}\prod_{p\leq z_1,\: p\in \mathcal{P}}\bigg(1-\dfrac{\mathfrak{g}(p)}{p}\bigg) - \sum_{\substack{p|d \Rightarrow p \in \mathcal{P}\\ d\leq D}}\lambda^-_{\textup{sem}}(d){E}(d),
\end{equation}
and
\begin{equation}
 S(\mathcal{C}, \mathcal{P}, z_1) \leq C(x)\bigg\{F_{\textup{sem}}(u_1) + o(1)\bigg\}\prod_{p\leq z_1,\: p\in \mathcal{P}}\bigg(1-\dfrac{\mathfrak{g}(p)}{p}\bigg)+\sum_{\substack{p|d \Rightarrow p \in \mathcal{P}\\ d\leq D}}\lambda^+_{\textup{sem}}(d){E}(d),
\end{equation}
where $f_{\textup{sem}}, F_{\textup{sem}}$ are continuous functions in $u_1 = \log D/\log z_1$ such that 
\begin{equation}
\begin{cases} 
\sqrt{u_1}F_{\textup{sem}}(u_1)=2\sqrt{e^\gamma/\pi} & \text{if}\quad 0 <u_1 \leq 2, \\ 
f_{\textup{sem}}(u_1) = 0 & \text{if}\quad 0<u_1\leq 1, 
\end{cases}
\end{equation}
where $\gamma$ is the Euler-Mascheroni constant, and 





for $1\leq u_1\leq 3$ we have
\begin{equation}
\dfrac{\sqrt{u_1}f_{\textup{sem}}(u_1)}{\sqrt{e^\gamma/\pi}}=\int_1^{u_1} \dfrac{\textup{d}y}{\sqrt{y(y-1)}}=\log \bigg(1+2(u_1-1)+2\sqrt{u_1(u_1-1)}\bigg).
\end{equation}

Consider a sequence $\mathcal{C} = \big(c(n)\big)_{n=1}^\infty\subset\mathbb{R}_{\geq 0}$ and a set of primes $\mathcal{P}$ satisfying axioms A1, A2, and A4 with $\varkappa = 1$. If $u_2>0$ and $D=z_2^{u_2}$, then there exist two arithmetic functions $\lambda^\pm_{\textup{lin}}: \mathbb{N}\rightarrow [-1, 1]$ supported on the set $\{d|P(z_2): d\leq D\}$, and we have
\begin{equation}
 S(\mathcal{C}, \mathcal{P}, z_2) \geq C(x)\Big\{f_{\textup{lin}}(u_2) + o(1)\Big\}\prod_{p\leq z_2,\: p\in \mathcal{P}}\bigg(1-\dfrac{\mathfrak{g}(p)}{p}\bigg) - \sum_{\substack{p|d \Rightarrow p \in \mathcal{P}\\ d\leq D}}\lambda^-_{\textup{lin}}(d){E}(d),
\end{equation}
and
\begin{equation}
S(\mathcal{C}, \mathcal{P}, z_2) \leq C(x)\Big\{F_{\textup{lin}}(u_2) + o(1)\Big\}\prod_{p\leq z_2,\: p\in \mathcal{P}}\bigg(1-\dfrac{\mathfrak{g}(p)}{p}\bigg) +\sum_{\substack{p|d \Rightarrow p \in \mathcal{P}\\ d\leq D}}\lambda^+_{\textup{lin}}(d){E}(d),
\end{equation}
where $f_{\textup{lin}}, F_{\textup{lin}}$ are continuous functions in $u_2 = \log D/\log z_2$ such that 
\begin{equation}
\begin{cases} 
u_2 F_{\textup{lin}}(u_2)=2e^\gamma & \text{if}\quad 1 \leq u_2 \leq 3, \\ 
f_{\textup{lin}}(u_2) = 0 & \text{if}\quad 0<u_2\leq 2,
\end{cases}
\end{equation}
where $\gamma$ is the Euler-Mascheroni constant.
